'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var realf = require( '@stdlib/complex/float32/real' );
var pow = require( '@stdlib/math/base/special/pow' );
var Complex64Tensor0D = require( '@stdlib/ndarray/tensor0d/complex64' );
var Int8Tensor0D = require( '@stdlib/ndarray/tensor0d/int8' );
var resolveEnum = require( '@stdlib/blas/base/transpose-operation-resolve-enum' );
var Complex64Vector = require( '@stdlib/ndarray/vector/complex64' );
var Complex64Matrix = require( '@stdlib/ndarray/matrix/complex64' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var cgemv = require( './../lib' );


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} N - number of elements along each dimension
* @returns {Function} benchmark function
*/
function createBenchmark( N ) {
	var trans;
	var alpha;
	var beta;
	var xbuf;
	var ybuf;
	var Abuf;
	var A;
	var x;
	var y;

	Abuf = uniform( N*N*2, -100.0, 100.0, {
		'dtype': 'float32'
	});
	A = new Complex64Matrix( Abuf.buffer, 0, [ N, N ] );

	xbuf = uniform( N*2, -100.0, 100.0, {
		'dtype': 'float32'
	});
	x = new Complex64Vector( xbuf.buffer );

	ybuf = uniform( N*2, -100.0, 100.0, {
		'dtype': 'float32'
	});
	y = new Complex64Vector( ybuf.buffer );

	alpha = new Complex64Tensor0D( 1.0, 0.0 );
	beta = new Complex64Tensor0D( 1.0, 0.0 );
	trans = new Int8Tensor0D( resolveEnum( 'no-transpose' ) );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = cgemv( [ A, x, y, trans, alpha, beta ] );
			if ( typeof z !== 'object' ) {
				b.fail( 'should return an ndarray' );
			}
		}
		b.toc();
		if ( isnanf( realf( z.get( i%N ) ) ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var N;
	var f;
	var i;

	min = 1; // 10^min
	max = 3; // 10^max

	for ( i = min; i <= max; i++ ) {
		N = pow( 10, i );
		f = createBenchmark( N );
		bench( format( '%s:size=%d', pkg, N*N ), f );
	}
}

main();
